 if(CAMPAIGN&&v>0){fee='<span class="pre"><span class="old">'+T[t]+'</span><span class="arw">▶</span></span><span class="new">'+Math.max(0,v-OFF).toLocaleString('ja-JP')+'<small>円'+SUF[t]+'</small></span><span class="post"></span>';}
